parameters.text:
=Investigate the following incident alert:
Incident Type: {{ $json.body.incident_type || 'Unknown' }}
Target Endpoint: {{ $json.body.endpoint || '/unknown' }}
Suspected IP: {{ $json.body.source_ip || 'N/A' }}
Anomaly Score: {{ $json.body.anomaly_score || 'N/A' }}
Error Count: {{ $json.body.error_count || 'N/A' }}

Step 1: Check the security runbook for recommended procedure.
Step 2: Inspect recent deployments to see if this was triggered by a bad code release.
Step 3: Output your Root Cause Analysis (RCA) and state clearly what mitigation action should be taken (e.g. 'block_ip', 'rate_limit', or 'rollback_deploy').

parameters.jsCode:
const incidentType = (query || '').toLowerCase();
if (incidentType.includes('brute') || incidentType.includes('auth')) {
  return JSON.stringify({
    runbook: 'Brute Force Attack Mitigation',
    procedure: '1. Verify failed login spikes. 2. Propose blocking IP at firewall. 3. Audit targeted accounts.'
  });
} else if (incidentType.includes('sql') || incidentType.includes('sqli')) {
  return JSON.stringify({
    runbook: 'SQL Injection Probing Mitigation',
    procedure: '1. Identify offending SQL syntax in URI. 2. Block offending IP immediately. 3. Patch vulnerable endpoint.'
  });
} else if (incidentType.includes('deploy') || incidentType.includes('500')) {
  return JSON.stringify({
    runbook: 'Bad Deploy Regression Mitigation',
    procedure: '1. Check recent release tag. 2. Verify 500 error spike coincides with release. 3. Propose rollback.'
  });
}
return JSON.stringify({ runbook: 'General Incident Investigation', procedure: 'Monitor logs and rate limit IP.' });

return JSON.stringify([
  { release_id: 'v2.4.1', deployed_at: '10 mins ago', author: 'dev-team', status: 'healthy' },
  { release_id: 'v2.4.0', deployed_at: '2 days ago', author: 'release-bot', status: 'stable' }
]);
